pub fn infer_builtin_call_type(name: String) -> Option<Rc<Node>> {
    v1_rt::map_get(&builtin_function_registry(), name.clone())
}

pub fn resolve_builtin_call_type(name: String) -> Rc<Node> {
    match infer_builtin_call_type(name.clone()) {
        Some(v) => v.clone(),
        None => unit_type(),
    }
}
